async function clickUnit(a,id){await a.page.evaluate(id=>__game.renderer.focusUnit(id),id);await a.page.waitForTimeout(350);const p=await a.page.evaluate(id=>{const p=__game.renderer.screenPoint(__game.sim.get(id)),r=__game.renderer.game.canvas.getBoundingClientRect(),cfg=__game.renderer.game.config;return {x:r.left+p.x/Number(cfg.width)*r.width,y:r.top+(p.y-27)/Number(cfg.height)*r.height};},id);await a.page.mouse.click(p.x,p.y);await a.page.locator('#contractPopover').waitFor({state:'visible'});if([4,5].includes(a.id))await a.page.locator(`[data-contract-role="${a.id}"]`).click();await a.page.locator('#confirmContract').click();await a.page.waitForFunction(id=>__game.sim.hero()?.classId===id,a.id);}
try{
 for(const id of [0,3,4,5,2]){const context=await browser.newContext({viewport:{width:1440,height:1200}}),page=await context.newPage();page.on('pageerror',e=>result.errors.push(e.message));await page.goto(base);await page.locator('#accountName').fill('持续检测'+id);await page.locator('#accountPassword').fill('isolated-runtime-audit');await page.locator(`[name="side"][value="${id===3?1:0}"]`).check();await page.locator('#authSubmit').click();await page.waitForFunction(()=>window.__game?.renderer.getCamera());actors.push({id,context,page,p:r.player(game.accounts.rows.at(-1))});}
 for(const a of actors)await check(`class${a.id} death->same class re-contract independent progress`,async()=>{let u=s.units.find(u=>!u.hero&&u.side===a.p.side&&u.type===contractType(a.id));await clickUnit(a,u.id);a.p.level=6;a.p.xp=1;a.p.builds[a.id]=[2,1,1,1];a.p.points=1;const before={progress:clone(a.p.progress[a.id]),build:clone(a.p.builds[a.id])};s.damage(null,s.hero(a.p),1e9);u=s.spawn(a.p.side,contractType(a.id),0,1,0);u.y=a.p.side?36:-56;await sync();await a.page.waitForFunction(()=>!__game.sim.hero());await a.page.locator('#skills').waitFor({state:'hidden'});await clickUnit(a,u.id);assert.deepEqual(a.p.progress[a.id],before.progress);assert.deepEqual(a.p.builds[a.id],before.build);return {before,after:{progress:a.p.progress[a.id],build:a.p.builds[a.id]}};});
 await check('rendered hero overlapping ordinary soldier cannot click through to soldier',async()=>{const a=actors[0],other=actors[2],h=s.hero(other.p);s.damage(null,s.hero(a.p),1e9);const u=s.spawn(0,'melee',0,1,0);Object.assign(u,{x:0,y:-50,speed:0});Object.assign(h,{x:0,y:-50,speed:0});await sync();await a.page.evaluate(id=>__game.renderer.focusUnit(id),h.id);await a.page.waitForTimeout(350);const point=await a.page.evaluate(id=>{const p=__game.renderer.screenPoint(__game.sim.get(id)),r=__game.renderer.game.canvas.getBoundingClientRect();return {x:r.left+p.x/500*r.width,y:r.top+(p.y-39)/Number(__game.renderer.game.config.height)*r.height};},h.id);await a.page.mouse.click(point.x,point.y);assert.equal(await a.page.evaluate(()=>__game.selection.id),null);await a.page.screenshot({path:`${dir}/overlap-hit-test.png`});return {hero:h.id,minion:u.id,selected:null,point};});
 await check('XP wrong class reproduction through real cast and re-contract clicks',async()=>{const a=actors[4],enemy=s.hero(actors[1].p),h=s.hero(a.p);s.units=s.units.filter(u=>u.hero);for(const u of s.units)Object.assign(u,{x:9,y:30,speed:0,cd:1e9});Object.assign(h,{x:0,y:0});Object.assign(enemy,{x:0,y:10,hp:10});for(const t of s.towers)t.x=100;s.waveAt=1e9;a.p.cd=[0,0,0,0];await sync();await a.page.locator('[data-cast="0"]').click();await a.page.waitForFunction(()=>__game.sim.player.cd[0]>__game.sim.time);advance(.4);assert.ok(s.projectiles.some(b=>b.sourceId===h.id));s.damage(null,h,1e9);const before=clone(a.p.progress);const u=s.spawn(0,'ranged',0,1,0);u.y=0;u.speed=0;await sync();await a.page.evaluate(id=>__game.renderer.focusUnit(id),u.id);await a.page.waitForTimeout(350);const pt=await a.page.evaluate(id=>{const p=__game.renderer.screenPoint(__game.sim.get(id)),r=__game.renderer.game.canvas.getBoundingClientRect();return{x:r.left+p.x/500*r.width,y:r.top+(p.y-27)/Number(__game.renderer.game.config.height)*r.height};},u.id);await a.page.mouse.click(pt.x,pt.y);await a.page.locator('[data-contract-role="4"]').click();await a.page.locator('#confirmContract').click();await a.page.waitForFunction(()=>__game.sim.hero()?.classId===4);advance(1.2);await sync();const delta={rune:s.players[a.p.id].progress[2].xp-before[2].xp,fire:s.players[a.p.id].progress[4].xp-before[4].xp};await a.page.screenshot({path:`${dir}/wrong-class-xp.png`});result.wrongXp={before,after:clone(a.p.progress),delta};assert.equal(delta.fire,0,JSON.stringify(delta));return delta;});
 // Fresh isolated battle, all five roles at level 6; no direct HP/position changes during runtime.
 s.resetMap();r.stageResetAt=s.metrics.resets;r.stageEnd=s.time+3600;for(const a of actors){a.p.stamina=100;a.p.progress[a.id]={level:6,xp:0,points:2};a.p.builds[a.id]=[1,1,1,1];a.p.cd=[0,0,0,0];s.setClass(a.id,a.p);a.p.auto=false;}await sync();
 for(const a of actors){const u=s.units.find(u=>!u.hero&&u.side===a.p.side&&u.type===contractType(a.id));await clickUnit(a,u.id);await a.page.locator('#auto').check();await a.page.waitForFunction(()=>__game.sim.player.auto);await a.page.locator('#locate').click();}
 await Promise.all(actors.map(a=>a.page.evaluate(()=>{window.__runtimeFrames=[];window.__runtimeSeq=[];let last=performance.now();const frame=now=>{__runtimeFrames.push(now-last);last=now;window.__runtimeRaf=requestAnimationFrame(frame);};__runtimeRaf=requestAnimationFrame(frame);window.__runtimeTimer=setInterval(()=>__runtimeSeq.push({at:performance.now(),sequence:__game.sim.sequence,connected:__game.network.connected,heroes:__game.sim.units.filter(u=>u.hero).length}),200);})));r.speed=4;r.paused=false;console.log('HERO_RUNTIME_START');const starts=s.metrics.casts;
 for(let i=0;i<12;i++){await actors[0].page.waitForTimeout(10000);for(const a of actors){if(s.hero(a.p)||a.p.stamina<s.config.world.contractCost)continue;const u=s.units.find(u=>!u.hero&&u.side===a.p.side&&u.type===contractType(a.id));if(u)await a.page.evaluate(({id,unitId})=>__game.network.send('contract',{classId:id,unitId}),{id:a.id,unitId:u.id});}result.samples.push({wallSeconds:(i+1)*10,time:s.time,units:s.units.length,heroes:s.units.filter(u=>u.hero).length,casts:s.metrics.casts,sequence:r.sequence,clients:r.clients.size,stamina:actors.map(a=>({id:a.id,stamina:a.p.stamina,auto:a.p.auto,heroId:a.p.heroId}))});if(i===5)console.log('HERO_RUNTIME_60_SECONDS');}
 r.paused=true;await sync();result.frames=await Promise.all(actors.map(a=>a.page.evaluate(()=>{cancelAnimationFrame(__runtimeRaf);clearInterval(__runtimeTimer);const arr=__runtimeFrames.sort((a,b)=>a-b);let longestFlat=0,start=__runtimeSeq[0];for(const v of __runtimeSeq){if(v.sequence!==start.sequence)start=v;longestFlat=Math.max(longestFlat,v.at-start.at);}return {samples:arr.length,p50:arr[Math.floor(arr.length*.5)],p95:arr[Math.floor(arr.length*.95)],max:arr.at(-1),over50ms:arr.filter(x=>x>50).length,longestFlat,sequence:__runtimeSeq};})));
 assert.ok(s.metrics.casts>starts+20);result.runtimePassed=true;await actors[0].page.locator('#viewFront').click();await actors[0].page.waitForTimeout(300);await actors[0].page.screenshot({path:`${dir}/hero-runtime-battle.png`});
}catch(e){result.fatal={error:e.message,stack:e.stack};}
finally{fs.writeFileSync(`${dir}/runtime-audit.json`,JSON.stringify(result,null,2));await browser.close();for(const c of [...r.clients])c.res.end();game.server.closeAllConnections();await new Promise(resolve=>game.server.close(resolve));console.log(JSON.stringify({checks:result.checks,runtimePassed:result.runtimePassed,samples:result.samples,frames:result.frames?.map(({sequence,...rest})=>rest),fatal:result.fatal,errors:result.errors},null,2));}
